{
  "sql": "SELECT p.product_id, p.product_name, SUM(oi.quantity) AS total_quantity FROM commerce.order_items AS oi INNER JOIN commerce.orders AS o ON oi.order_id = o.order_id INNER JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_date >= $1 AND o.order_date < $2 AND LOWER(o.order_status) NOT IN ('cancelled', 'canceled') GROUP BY p.product_id, p.product_name ORDER BY 3 DESC, p.product_id ASC LIMIT 20",
  "parameters": ["2022-01-01", "2023-01-01"],
  "explanation": "Joins order_items with orders and products to aggregate total quantity sold per product in 2022, excluding cancelled orders. Orders are filtered by date range and status. Results are sorted by total quantity descending, with product_id as a tie-breaker, limited to the top 20."
}
